using UnityEngine;using UnityEngine.AI;using System.Collections;using System.IO;
public class TrailClueMarkerProbe:MonoBehaviour {
 IEnumerator Start(){const string e="Evidence/trail-clue-marker-20261030/";var marker=FindObjectOfType<TrailClueMarker>();var movement=GetComponent<DemoMovement>();var agent=GetComponent<NavMeshAgent>();var target=marker.clue;yield return new WaitForSeconds(.7f);var approach=target.transform.position+new Vector3(-2,0,-2);NavMesh.SamplePosition(approach,out var h,3,NavMesh.AllAreas);agent.Warp(h.position);yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"gameplay.png"));yield return new WaitForSeconds(.3f);var cam=movement.viewCamera;var follow=cam.GetComponent<DemoCamera>();if(follow)follow.enabled=false;cam.transform.position=target.transform.position+new Vector3(-3,4.5f,-6);cam.transform.LookAt(target.transform.position+Vector3.up*.6f);yield return new WaitForSeconds(.5f);ScreenCapture.CaptureScreenshot(Path.GetFullPath(e+"detail.png"));var ray=cam.ScreenPointToRay(cam.WorldToScreenPoint(target.transform.position+Vector3.up*.7f));bool hit=Physics.Raycast(ray,out var result,50);bool selectable=hit&&result.collider.GetComponent<DemoInteractable>()==target;File.WriteAllText(e+"playmode.txt","Unity="+Application.unityVersion+" scene="+gameObject.scene.name+"\nraycastSelectable="+selectable+" hit="+(hit?result.collider.name:"none")+" clueId="+target.clueId+"\n");movement.BeginInteraction(target);yield return new WaitForSeconds(1.8f);File.AppendAllText(e+"playmode.txt","examined="+target.examined+" HasTrail="+GetComponent<DemoInvestigation>().HasTrail+" badgeHidden="+!marker.badge.gameObject.activeSelf+" path="+agent.pathStatus+"\n");if(follow)follow.enabled=true;}
}
